function moduleFrame(src,title){if(!navigator.onLine)return `<section class="panel module-offline" role="status"><h2>${h(title)} için bağlantı gerekli</h2><p>Bu bölüm kişisel bilgilerini sunucudan alır ve cihazda saklanmaz. İnternet bağlantısı gelince otomatik açılır.</p><button class="btn primary" type="button" data-act="retry">Tekrar dene</button></section>`;return `<div class="module-loading" role="status" aria-live="polite"><span class="spinner" aria-hidden="true"></span><span class="module-loading-text">${h(title)} yükleniyor…</span></div><iframe class="module-frame" title="${h(title)}" src="${src}" allow="camera; screen-wake-lock; fullscreen"></iframe>`}
