// Renewal buckets from the membership end date (Istanbul calendar day).
const RENEW={expired:'Süresi dolmuş',d7:'7 gün içinde bitiyor',d30:'30 gün içinde bitiyor',pending:'Yenileme bekliyor'};
function renewalBucket(m){const d=TT.daysUntil(m.expires);if(d!==null&&d<0)return 'expired';if(m.status!=='Aktif')return 'pending';if(d!==null&&d<=7)return 'd7';if(d!==null&&d<=30)return 'd30';return null}
function renewalsView(){const rows=members().map(m=>({m,b:renewalBucket(m),d:TT.daysUntil(m.expires)})).filter(x=>x.b).sort((a,b)=>(a.d??0)-(b.d??0)),count=k=>rows.filter(x=>x.b===k).length,list=renewFilter?rows.filter(x=>x.b===renewFilter):rows;
 const left=d=>d===null?'—':d<0?`${-d} gün geçti`:d===0?'Bugün bitiyor':`${d} gün`;
 const hist=(R||[]).slice(0,30).map(r=>`<tr><td>${h(TT.dateTime(TT.fromSqlUtc(r.created_at)))}</td><td>${h(r.member)}</td><td>${fdate(r.old_expires)} → ${fdate(r.new_expires)}</td><td>${h(r.credits)}</td><td>${h(r.actor||'')}</td></tr>`).join('');
 return `<div class="stats">${stat(RENEW.expired,count('expired'),'Yenilenmeli','!')}${stat(RENEW.d7,count('d7'),'Hatırlatma','◷')}${stat(RENEW.d30,count('d30'),'Planla','▤')}${stat(RENEW.pending,count('pending'),'Aktif olmayan','↻')}</div><section class="panel"><div class="panel-title"><h2>Üyelik yenileme <span class="muted">(${list.length})</span></h2><label class="fc-filter"><span>Durum</span><select id="renewFilter"><option value="">Tümü (${rows.length})</option>${Object.entries(RENEW).map(([k,v])=>`<option value="${k}" ${k===renewFilter?'selected':''}>${v} (${count(k)})</option>`).join('')}</select></label></div><p class="muted small">Süresi dolan, 30 gün içinde bitecek ve aktif olmayan üyelikler. Yenileme yalnızca bitiş tarihini ve ders hakkını günceller; ödeme kaydı oluşturmaz.</p><div class="table-wrap"><table><thead><tr><th>Üye</th><th>Paket</th><th>Bitiş</th><th>Kalan gün</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${list.map(({m,b,d})=>`<tr><td><strong>${h(m.name)}</strong><div class="muted">${h(m.phone||'')}</div></td><td>${h(m.plan)}</td><td>${fdate(m.expires)}</td><td>${left(d)}</td><td>${pill(RENEW[b],b==='d30'?'':b==='d7'?'warn':'bad')}</td><td>${btn('Yenile','renew:'+m.id,'small primary')} ${btn('Detay','profile:'+m.id,'small')}</td></tr>`).join('')||'<tr><td colspan="6">Bu filtrede yenilenecek üyelik yok.</td></tr>'}</tbody></table></div></section><section class="panel"><h2>Son yenilemeler</h2>${hist?`<div class="table-wrap"><table><thead><tr><th>Zaman</th><th>Üye</th><th>Bitiş</th><th>Ders hakkı</th><th>Yapan</th></tr></thead><tbody>${hist}</tbody></table></div>`:'<p class="muted">Henüz yenileme kaydı yok.</p>'}</section>`}
function leadStats(){const counts={};for(const l of L)counts[l.stage]=(counts[l.stage]||0)+1;return `<div class="stats">${stat('Yeni aday',counts['Yeni']||0,'İlk iletişim','◎')}${stat('Arandı',counts['Arandı']||0,'Takip','☎')}${stat('Deneme dersi',counts['Deneme Dersi']||0,'Potansiyel üye','▤')}${stat('Dönüştü',counts['Üyeye Dönüştü']||0,'Üyeliğe geçen','✓')}</div>`}
function leadsView(){return `${leadStats()}<section class="panel"><div class="panel-title"><div><h2>Müşteri adayları <span class="muted">(${L.length})</span></h2><p class="muted">Başvuru ve satış takip hattı · SMS gönderimi yapılmaz</p></div>${btn('+ Aday ekle','modal:lead','primary')}</div><div class="table-wrap"><table><thead><tr><th>Ad soyad</th><th>Telefon</th><th>İlgi alanı</th><th>Aşama</th><th>Not</th><th>İşlem</th></tr></thead><tbody>${L.map(l=>`<tr><td><strong>${h(l.name)}</strong></td><td>${h(l.phone)}</td><td>${h(l.interest)}</td><td>${pill(l.stage)}</td><td>${h(l.note)}</td><td>${btn('Aşama değiştir','leadstage:'+l.id,'small')}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">Henüz müşteri adayı eklenmedi.</td></tr>'}</tbody></table></div></section>`}
function memberDetail(){const m=members().find(x=>x.id===selectedMemberProfile);if(!m)return '<section class="panel">Üye bulunamadı.</section>';const bookings=S.bookings.filter(x=>x.member_id===m.id),payments=S.payments.filter(x=>x.member_id===m.id),visits=S.checkins.filter(x=>x.member_id===m.id),measurements=S.measurements.filter(x=>x.member_id===m.id);return `<div class="panel-title"><h2>${h(m.name)} · Üye dosyası</h2>${btn('← Üyelere dön','go:members','ghost')}</div><div class="stats">${stat('Kalan hak',m.credits,h(m.plan),'▤')}${stat('Bitiş',fdate(m.expires),h(m.status),'◷')}${stat('Derse katılım',bookings.filter(x=>x.status==='attended').length,'Onaylı yoklama','✓')}${stat('Salon girişi',visits.length,'Kayıtlı ziyaret','▦')}</div><div class="cols"><section class="panel"><div class="panel-title"><h2>Üyelik & iletişim</h2>${btn('Yenile','renew:'+m.id,'small primary')}</div><p>Telefon: ${h(m.phone||'-')}</p><p>E-posta: ${h(m.email||'-')}</p><p>Paket: ${h(m.plan)}</p><h3>Ders geçmişi</h3><div class="table-wrap"><table><thead><tr><th>Ders</th><th>Tarih</th><th>Durum</th></tr></thead><tbody>${bookings.slice(0,30).map(b=>`<tr><td>${h(b.class_title)}</td><td>${h(TT.dateTime(b.starts_at))}</td><td>${pill(b.status)}</td></tr>`).join('')||'<tr><td colspan="3">Kayıt yok</td></tr>'}</tbody></table></div></section><section class="panel"><h2>Ödeme geçmişi</h2>${payments.map(p=>`<div class="teacher-person"><div class="avatar">₺</div><div class="name">${money(p.amount)}<div class="muted">${fdate(p.due_date)}</div></div>${pill(p.status)}</div>`).join('')||'<div class="empty">Kayıt yok</div>'}<h2 style="margin-top:24px">Ölçümler</h2>${measurements.slice(-4).map(x=>`<p>${fdate(x.measured_at)} · ${h(x.weight)} kg · Yağ %${h(x.body_fat)}</p>`).join('')||'<p>Ölçüm yok</p>'}<div class="panel-title" style="margin-top:24px"><h2>Üye notları</h2>${btn('+ Not','note:'+m.id,'small')}</div>${notes.map(n=>`<div class="hero"><p>${h(n.note)}</p><small class="muted">${h(TT.dateTime(TT.fromSqlUtc(n.created_at)))}</small></div>`).join('')||'<p class="muted">Henüz not yok.</p>'}</section></div>`}
function downloadCsv(which){const rows=which==='members'?[['Ad soyad','Telefon','E-posta','Paket','Bitiş','Ders hakkı','Durum'],...S.members.map(m=>[m.name,m.phone,m.email,m.plan,m.expires,m.credits,m.status])]:[['Üye','Tutar','Durum','Vade','Ödeme tarihi'],...S.payments.map(p=>[p.member,p.amount,p.status,p.due_date,p.paid_at||''])];const safe=v=>{let x=String(v??'');if(/^[\s]*[=+@\-]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'};const csv='\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download='formclub-'+which+'-'+localDay(0)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function dayChips(){return `<div class="chips">${Array.from({length:7},(_,i)=>{const d=new Date(localDay(i)+'T12:00:00');return `<button class="chip ${day===i?'active':''}" data-day="${i}">${i===0?'Bugün':d.toLocaleDateString('tr-TR',{weekday:'short',day:'numeric'})}</button>`}).join('')}</div>`}
function classCards(list,memberActions=true){return `<div class="classes">${list.map(c=>{const mine=S.bookings.find(b=>b.member_id===memberId&&b.class_id===c.id&&['reserved','waitlist','attended'].includes(b.status));const full=c.booked>=c.capacity;return `<div class="class"><div class="time">${h(c.starts_at.slice(11,16))}</div><div class="details"><strong>${h(c.title)}</strong><small>${h(c.trainer)} · ${h(c.studio)} · ${h(c.booked)}/${h(c.capacity)} dolu</small><div class="progress"><div class="bar ${full?'full':''}" style="width:${Math.min(100,100*c.booked/c.capacity)}%"></div></div></div>${memberActions?mine?pill(mine.status==='waitlist'?'Sıradasın':'Yerin hazır',mine.status==='waitlist'?'warn':''):btn(full?'Sıraya gir':'Yer ayır','reserve:'+c.id,'small '+(full?'':'primary')):''}</div>`}).join('')||'<div class="empty">Seçilen gün için ders yok.</div>'}</div>`}
function classManagement(){return `<section class="panel"><div class="panel-title"><div><h2>Haftalık ders takvimi</h2><p class="muted">Eğitmen, stüdyo, kapasite ve saatleri tek ekrandan takip edin.</p></div>${btn('+ Yeni ders','modal:class','primary')}</div>${weeklyCalendar(S.classes)}<h3>Tekrarlayan ders planla</h3><div class="v6-repeat">${S.classes.filter(c=>!TT.isPast(c.starts_at)).sort(byStart).slice(0,40).map(c=>`<div>${h(c.title)} · ${h(TT.dateTime(c.starts_at,{weekday:true}))} ${btn("Haftalık çoğalt","v6repeat:"+c.id,"small ghost")}</div>`).join("")}</div></section>`}
function paymentsView(){return `<section class="panel"><div class="panel-title"><h2>Ödeme kayıtları</h2><div class="toolbar">${btn('CSV dışa aktar','csv:payments','ghost')}${btn('+ Ödeme ekle','modal:payment','primary')}</div></div><div class="table-wrap"><table><thead><tr><th>Üye</th><th>Tutar</th><th>Vade</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${S.payments.map(p=>`<tr><td>${h(p.member)}</td><td>${money(p.amount)}</td><td>${fdate(p.due_date)}</td><td>${pill(p.status,p.status==='Ödendi'?'':'warn')}</td><td>${p.status==='Bekliyor'?btn('Ödendi işaretle','pay:'+p.id,'small primary'):'—'}</td></tr>`).join('')}</tbody></table></div></section>`}
function trainersView(){return `<div class="cols">${S.trainers.map(t=>`<section class="panel"><div class="teacher-person"><div class="avatar">${h(t.name.slice(0,1))}</div><div><strong>${h(t.name)}</strong><div class="muted">${h(t.specialty)}</div></div></div><p>Programdaki ders sayısı: <strong>${S.classes.filter(c=>c.trainer_id===t.id).length}</strong></p></section>`).join('')}</div>`}
function announceView(){return `<section class="panel"><div class="panel-title"><h2>Salon duyuruları</h2>${btn('+ Duyuru ekle','modal:announcement','primary')}</div>${S.announcements.map(a=>`<div class="hero"><h3>${h(a.title)}</h3><p>${h(a.body)}</p><small class="muted">${h(TT.dateTime(TT.fromSqlUtc(a.created_at)))}</small></div>`).join('')}</section>`}
function reports(){const reservations=S.bookings.filter(b=>b.status==='reserved'||b.status==='attended');const attended=S.bookings.filter(b=>b.status==='attended');const collected=S.payments.filter(p=>p.status==='Ödendi').reduce((a,p)=>a+p.amount,0);return `<div class="stats">${stat('Üye sayısı',members().length,'Toplam kayıt','♙')}${stat('Rezervasyonlar',reservations.length,'Aktif kayıt','▤')}${stat('Katılım',attended.length,'İşlenen yoklama','✓')}${stat('Tahsilat',money(collected),'Ödenmiş kayıtlar','₺')}</div><section class="panel"><h2>Ders doluluğu</h2>${byDay().map(c=>`<div style="margin:18px 0"><div class="panel-title"><span>${h(c.title)} · ${h(c.starts_at.slice(11,16))}</span><b>${h(c.booked)}/${h(c.capacity)}</b></div><div class="progress"><div class="bar" style="width:${100*c.booked/c.capacity}%"></div></div></div>`).join('')}</section>`}
function memberHome(){const m=selected();if(!m)return '';const my=S.bookings.filter(b=>b.member_id===m.id&&b.status==='reserved');const next=S.classes.find(c=>my.some(b=>b.class_id===c.id));return `<div class="phone"><div class="eyebrow">FORM CLUB</div><h1>Günaydın, ${h(m.name.split(' ')[0])} 👋</h1><div class="stat" style="margin-top:22px"><div class="label">ÜYELİĞİN · ${h(m.plan)}</div><div class="value">${h(m.credits)}</div><div class="note">ders hakkın kaldı · Bitiş: ${fdate(m.expires)}</div></div><div class="panel" style="margin-top:17px"><h3>BUGÜNKÜ / YAKLAŞAN DERSİN</h3>${next?`<p>${h(TT.dateTime(next.starts_at,{weekday:true}))}</p><strong>${h(next.title)}</strong><p>${h(next.trainer)} · ${h(next.duration)} dk</p>${btn('Gelemeyeceğim','cancel:'+my.find(b=>b.class_id===next.id)?.id,'small')}`:'<p>Henüz rezervasyonun yok.</p>'}</div><div class="cols" style="grid-template-columns:1fr 1fr"><div class="panel" style="text-align:center"><div style="font-size:32px">▦</div><h3>QR Giriş</h3>${btn('Kodumu gör','go:entry','small')}</div><div class="panel" style="text-align:center"><div style="font-size:32px;color:#b6f548">${S.checkins.filter(i=>i.member_id===m.id).length}</div><small>Toplam giriş</small></div></div>${S.announcements.slice(0,1).map(a=>`<div class="panel"><span class="eyebrow">DUYURU</span><h3>${h(a.title)}</h3><p>${h(a.body)}</p></div>`).join('')}</div>`}
function memberLessons(){const m=selected();return `<div class="phone"><div class="panel-title"><h2>Dersler</h2>${pill(m?.credits+' hakkın var')}</div>${dayChips()}${classCards(byDay())}</div>`}
function memberEntry(){return moduleFrame('/v9/index.html?embedded=1#qr','QR kodum')}
function memberProgress(){const m=selected();const ms=S.measurements.filter(x=>x.member_id===m.id);const last=ms[ms.length-1];return `<div class="phone"><h1>Gelişimin</h1><div class="chips">${['Kilo','Yağ oranı','Ölçüler'].map((x,i)=>`<span class="chip ${i===0?'active':''}">${x}</span>`).join('')}</div><div class="hero"><div class="big">${ms.length>1?(last.weight-ms[0].weight).toFixed(1):'—'} kg</div><span class="muted">İlk ölçüme göre değişim</span></div><div class="meter">${ms.map(x=>`<div class="metercol"><div style="height:${Math.max(15,(x.weight||0)*1.6)}px"></div>${fdate(x.measured_at).split(' ')[1]}</div>`).join('')}</div><div class="stats" style="grid-template-columns:repeat(3,1fr)">${[['Kilo',last?.weight],['Yağ %',last?.body_fat],['Kas',last?.muscle]].map(x=>`<div class="panel" style="text-align:center;padding:12px"><small>${x[0]}</small><h2 style="margin-top:8px">${x[1]??'—'}</h2></div>`).join('')}</div>${btn('+ Yeni ölçüm','modal:measurement','primary')}</div>`}
function memberProfile(){const m=selected();return `<div class="phone"><h1>Profil</h1><div class="hero"><h2>${h(m.name)}</h2><p>${h(m.phone)}<br>${h(m.email)}</p>${pill(m.status)}</div><section class="panel"><h3>Üyelik bilgilerim</h3><p>Paket: ${h(m.plan)}<br>Kalan hak: ${h(m.credits)}<br>Bitiş: ${fdate(m.expires)}</p></section><section class="panel"><h3>Rezervasyonlarım</h3>${S.bookings.filter(b=>b.member_id===m.id).slice(0,8).map(b=>`<div class="teacher-person"><div class="name">${h(b.class_title)}<div class="muted">${h(TT.dateTime(b.starts_at))}</div></div>${pill(b.status,b.status==='cancelled'?'bad':'')}</div>`).join('')||'<p>Henüz kayıt yok.</p>'}</section>${energyView()}</div>`}
function teacherToday(){const list=byDay().filter(c=>c.trainer_id===teacherId);return `<div class="stats">${stat('Ders bugün',list.length,'Günlük program','▤')}${stat('Ders bu hafta',S.classes.filter(c=>c.trainer_id===teacherId).length,'Planlı dersler','◷')}</div>${dayChips()}${list.map(c=>`<section class="panel"><div class="panel-title"><div><span class="eyebrow">${h(c.starts_at.slice(11,16))} · ${h(c.studio)}</span><h2>${h(c.title)}</h2></div>${pill(c.booked+' / '+c.capacity+' kişi')}</div>${S.bookings.filter(b=>b.class_id===c.id&&['reserved','attended','absent'].includes(b.status)).map(b=>`<div class="teacher-person"><div class="avatar">${h(b.member.slice(0,1))}</div><span class="name">${h(b.member)}</span>${b.status==='attended'?pill('Geldi'):b.status==='absent'?pill('Gelmedi','bad'):`${btn('Geldi','attend:'+b.id,'small primary')}${btn('Gelmedi','absent:'+b.id,'small')}`}</div>`).join('')||'<p>Henüz kayıtlı katılımcı yok.</p>'}</section>`).join('')||'<div class="panel empty">Bu gün için dersin yok.</div>'}`}
function startOfWeek(offset=0){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7)+offset*7);return d}
function weekDates(offset=0){const d=startOfWeek(offset);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`})}
function weeklyCalendar(classes){const dates=weekDates(weekOffset),first=new Date(dates[0]+'T12:00:00'),last=new Date(dates[6]+'T12:00:00');const label=d=>d.toLocaleDateString('tr-TR',{day:'numeric',month:'short'});return `<div class="calendar-tools"><div><span class="eyebrow">HAFTALIK PLAN</span><h3>${label(first)} – ${label(last)}</h3></div><div class="calendar-buttons"><button class="btn small" data-act="week:prev">← Önceki</button><button class="btn small ghost" data-act="week:today">Bu hafta</button><button class="btn small" data-act="week:next">Sonraki →</button></div></div><div class="week-scroll"><div class="week-grid">${dates.map(date=>{const items=classes.filter(c=>c.starts_at.slice(0,10)===date);const d=new Date(date+'T12:00:00');return `<div class="week-day ${date===localDay(0)?'week-current':''}"><div class="week-day-head"><span>${d.toLocaleDateString('tr-TR',{weekday:'short'})}</span><strong>${d.getDate()}</strong></div><div class="week-events">${items.map(c=>`<div class="calendar-event"><span class="cal-time">${h(c.starts_at.slice(11,16))}</span><strong>${h(c.title)}</strong><small>${h(c.trainer||'')} · ${h(c.studio)}</small><span class="cal-cap">${h(c.booked)}/${h(c.capacity)} kişi</span></div>`).join('')||'<span class="week-empty">Ders yok</span>'}</div></div>`}).join('')}</div></div>`}
function teacherCalendar(){return `<section class="panel"><div class="panel-title"><h2>Haftalık ders takvimim</h2>${btn('+ Öğrenci ekle','modal:student','primary')}</div>${weeklyCalendar(S.classes.filter(c=>c.trainer_id===teacherId))}</section>`}
function teacherStudents(){const ids=new Set(S.bookings.filter(b=>S.classes.some(c=>c.id===b.class_id&&c.trainer_id===teacherId)).map(b=>b.member_id));const students=members().filter(m=>ids.has(m.id));return `<section class="panel"><div class="panel-title"><div><h2>Öğrencilerim <span class="muted">(${students.length})</span></h2><p class="muted">Derslerinize kayıtlı öğrenciler</p></div>${btn('+ Yeni öğrenci','modal:student','primary')}</div><div class="student-grid">${students.map(m=>`<div class="student-card"><div class="avatar">${h(m.name[0])}</div><div><strong>${h(m.name)}</strong><div class="muted">${h(m.plan||'Üye')}</div>${pill((m.credits??0)+' ders hakkı')}</div></div>`).join('')||'<div class="empty">Henüz öğrenciniz yok. İlk öğrenciyi eklemek için sağ üstteki butonu kullanın.</div>'}</div></section>`}
function teacherProfile(){const t=S.trainers.find(x=>x.id===teacherId);return `<section class="panel"><h2>${h(t?.name)}</h2><p>Uzmanlık alanı: ${h(t?.specialty)}</p><p>Planlı ders sayısı: ${S.classes.filter(c=>c.trainer_id===teacherId).length}</p></section>${energyView()}`}
function v6MonthCalendar(classes){const base=new Date();base.setDate(1);base.setMonth(base.getMonth()+v6MonthOffset);const year=base.getFullYear(),month=base.getMonth(),first=(base.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),cells=Math.ceil((first+days)/7)*7;const fmt=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const bydate=new Map();for(const c of classes){const k=cday(c);bydate.set(k,(bydate.get(k)||[]).concat(c))}const selectedDate=v6CalendarDate||fmt(new Date());return `<div class="calendar-tools"><h3>${base.toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</h3><div class="calendar-buttons">${btn('← Ay','v6month:prev','small ghost')}${btn('Bugün','v6month:today','small')}${btn('Sonraki ay →','v6month:next','small ghost')}</div></div><div class="v6-month-grid">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(d=>`<div class="v6-month-head">${d}</div>`).join('')}${Array.from({length:cells},(_,i)=>{const d=new Date(year,month,1-first+i),key=fmt(d),list=bydate.get(key)||[],different=d.getMonth()!==month;return `<button type="button" class="v6-month-day ${different?'v6-outside':''} ${key===selectedDate?'v6-selected':''}" data-act="v6date:${key}"><strong>${d.getDate()}</strong>${list.length?`<span class="v6-day-count">${list.length} ders</span>`:''}</button>`}).join('')}</div><h3>${fdate(selectedDate)} dersleri</h3>${classCards((bydate.get(selectedDate)||[]))}`}
function v6MemberCalendar(){return `<section class="panel"><div class="panel-title"><div><h2>Üye ders takvimi</h2><p class="muted">${V6.settings.booking_window_days} gün ileriye kadar rezervasyon yapılabilir. İleri tarihte ders yoksa yönetici ders planı eklemeli.</p></div><div class="toolbar">${btn('Aylık görünüm','v6calendar:month',v6CalendarMode==='month'?'primary':'ghost')}${btn('Haftalık görünüm','v6calendar:week',v6CalendarMode==='week'?'primary':'ghost')}</div></div>${v6CalendarMode==='month'?v6MonthCalendar(S.classes):weeklyCalendar(S.classes)+`<h3>Seçili haftanın dersleri</h3>${classCards(S.classes.filter(c=>weekDates(weekOffset).includes(cday(c))))}`}</section>`}

function v6Bar(label,value,max,extra=''){const width=max>0?Math.min(100,Math.round(100*value/max)):0;return `<div class="v6-bar-row"><span>${h(label)}</span><div class="progress"><div class="bar" style="width:${width}%"></div></div><b>${extra||value}</b></div>`}
function v6Insights(){const records=V6.analytics?.monthly||[];const years=[...new Set(records.map(r=>r.month.slice(0,4)))].sort().reverse(),max=Math.max(1,...records.map(r=>r.collected));const yearly=years.map(y=>({year:y,collected:records.filter(r=>r.month.startsWith(y)).reduce((s,r)=>s+r.collected,0),attended:records.filter(r=>r.month.startsWith(y)).reduce((s,r)=>s+r.attended,0)}));return `<section class="panel"><h2>Aylık tahsilat ve katılım</h2><p class="muted">Gerçek ödeme ve yoklama kayıtlarından hesaplanır. Veri olmayan aylar için değer uydurulmaz.</p>${records.map(r=>v6Bar(r.month,r.collected,max,money(r.collected))+`<div class="muted">Katılım: ${r.attended} / işlenen: ${r.marked}</div>`).join('')||'<div class="empty">Henüz raporlanacak işlem yok.</div>'}</section><section class="panel"><h2>Yıllık karşılaştırma</h2>${yearly.map(r=>`<div class="v6-year"><strong>${r.year}</strong><span>${money(r.collected)} tahsilat</span><span>${r.attended} katılım</span></div>`).join('')||'<div class="empty">Yıllık kayıt yok.</div>'}</section><section class="panel"><h2>Öğrenci süreklilik ve ödeme göstergeleri</h2><p class="muted">Devamlılık: geldi / işlenen yoklama. Ödeme düzeni: zamanında ödenen / tüm ödeme kayıtları. Veri yoksa puan hesaplanmaz.</p><div class="table-wrap"><table><thead><tr><th>Öğrenci</th><th>Devamlılık</th><th>Ödeme düzeni</th><th>Yoklama</th></tr></thead><tbody>${(V6.analytics?.scores||[]).map(s=>`<tr><td>${h(s.name)}</td><td>${s.attendance_score===null?'Veri yok':s.attendance_score+' / 100'}</td><td>${s.payment_score===null?'Veri yok':s.payment_score+' / 100'}</td><td>${s.attended}/${s.marked}</td></tr>`).join('')}</tbody></table></div></section>`}
function v6Settings(){const s=V6.settings;return `<section class="panel"><h2>Rezervasyon ve topluluk ayarları</h2><p class="muted">Yalnızca yönetici değiştirebilir.</p><form id="v6SettingsForm" class="v6-form"><label>Kaç gün önceden ders seçilsin? (1–365)<input name="booking_window_days" type="number" min="1" max="365" value="${s.booking_window_days}" required></label><h3>Paylaşım yapabilecek roller</h3>${[['admin','Yönetici'],['teacher','Eğitmen'],['member','Üye']].map(([v,label])=>`<label class="v6-check"><input type="checkbox" name="posts" value="${v}" ${s.community_post_roles.includes(v)?'checked':''}> ${label}</label>`).join('')}<h3>Yorum yapabilecek roller</h3>${[['admin','Yönetici'],['teacher','Eğitmen'],['member','Üye']].map(([v,label])=>`<label class="v6-check"><input type="checkbox" name="comments" value="${v}" ${s.community_comment_roles.includes(v)?'checked':''}> ${label}</label>`).join('')}<button class="btn primary" type="submit">Ayarları kaydet</button></form></section>`}
function v6Community(){const canPost=V6.settings.community_post_roles.includes(role),canComment=V6.settings.community_comment_roles.includes(role);return `<section class="panel"><h2>FORM CLUB Topluluğu</h2><p class="muted">Paylaşımlar sadece oturum açmış kullanıcılara görünür. Yönetici tüm gönderileri kaldırabilir.</p>${canPost?`<form id="v6PostForm" class="v6-form"><label>Yeni paylaşım<textarea name="text" maxlength="2000" required placeholder="Toplulukla ne paylaşmak istersin?"></textarea></label><button class="btn primary">Paylaş</button></form>`:'<p class="muted">Bu hesap için paylaşım kapalı.</p>'}</section>${V6.posts.map(p=>`<section class="panel"><div class="panel-title"><div><strong>${h(p.username)}</strong> ${pill(p.role)}<div class="muted">${h(TT.dateTime(TT.fromSqlUtc(p.created_at)))}</div></div>${role==='admin'||p.user_id===account.id?btn('Kaldır','v6deletepost:'+p.id,'small ghost'):''}</div><p class="v6-post-body">${h(p.body)}</p><div class="v6-comments">${p.comments.map(c=>`<div class="v6-comment"><b>${h(c.username)}</b> ${h(c.body)} ${role==='admin'||c.user_id===account.id?btn('×','v6deletecomment:'+c.id,'small ghost'):''}</div>`).join('')}</div>${canComment?`<form class="v6CommentForm v6-inline" data-id="${p.id}"><input name="text" maxlength="500" required placeholder="Yorum yaz..."><button class="btn small">Gönder</button></form>`:''}</section>`).join('')||'<div class="empty">Henüz paylaşım yapılmadı.</div>'}`}
function v6Nutrition(){const chosen=role==='member'?memberId:V6.memberFilter,logs=V6.logs||[],date=localDay(0),daily=logs.filter(l=>l.consumed_on===date),sum=daily.reduce((s,l)=>s+l.grams*l.kcal_100g/100,0);return `<section class="panel"><div class="panel-title"><div><h2>Beslenme günlüğü</h2><p class="muted">Ürün besin değerleri manuel girilir; harici doğrulanmış besin veri tabanı bağlı değildir. Bu kayıtlar tıbbi tavsiye değildir.</p></div></div>${role==='admin'?`<label>Öğrenci seç<select id="v6MemberFilter">${members().map(m=>`<option value="${m.id}" ${chosen===m.id?'selected':''}>${h(m.name)}</option>`).join('')}</select></label>`:''}<div class="stats">${stat('Bugün kaydedilen enerji',Math.round(sum)+' kcal',daily.length+' kayıt','◉')}${stat('Besin kataloğu',V6.foods.length,'Manuel ürün','♧')}</div><div class="v6-split"><form id="v6FoodForm" class="panel v6-form"><h3>Ürün ekle (100 gram için)</h3><label>Ürün adı<input name="name" required maxlength="100"></label><label>Kalori (kcal)<input name="kcal_100g" type="number" min="0" max="1000" step="0.1" required></label><label>Protein (g)<input name="protein_100g" type="number" min="0" max="100" step="0.1" value="0"></label><label>Karbonhidrat (g)<input name="carbs_100g" type="number" min="0" max="100" step="0.1" value="0"></label><label>Yağ (g)<input name="fat_100g" type="number" min="0" max="100" step="0.1" value="0"></label><button class="btn primary">Ürünü kaydet</button></form><form id="v6LogForm" class="panel v6-form"><h3>Öğün kaydet</h3><label>Ürün<select name="product_id" required>${V6.foods.map(f=>`<option value="${f.id}">${h(f.name)} · ${h(f.kcal_100g)} kcal/100g</option>`).join('')}</select></label><label>Miktar (gram)<input name="grams" type="number" min="1" max="5000" step="0.1" value="100" required></label><label>Tarih<input name="consumed_on" type="date" value="${date}" required></label><button class="btn primary" ${!V6.foods.length?'disabled':''}>Günlüğe ekle</button></form></div></section><section class="panel"><h2>Son kayıtlar</h2><div class="table-wrap"><table><thead><tr><th>Tarih</th><th>Ürün</th><th>Gram</th><th>Kalori</th><th></th></tr></thead><tbody>${logs.map(l=>`<tr><td>${h(l.consumed_on)}</td><td>${h(l.name)}</td><td>${h(l.grams)}</td><td>${Math.round(l.grams*l.kcal_100g/100)} kcal</td><td>${btn('Sil','v6deletelog:'+l.id,'small ghost')}</td></tr>`).join('')||'<tr><td colspan="5">Henüz beslenme kaydı yok.</td></tr>'}</tbody></table></div></section>`}
function modal(title,fields,submitLabel='Kaydet'){document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="modal"><div class="modal"><div class="modalhead"><h2>${title}</h2><button class="close" data-act="close">×</button></div><form id="entryForm"><div class="form-grid">${fields}</div><div class="toolbar" style="justify-content:flex-end;margin-top:20px"><button class="btn ghost" type="button" data-act="close">Vazgeç</button><button class="btn primary" type="submit">${submitLabel}</button></div></form></div></div>`)}
const fld=(label,name,type='text',val='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${h(val)}" ${extra}></label>`;
const sel=(label,name,items,selectedVal)=>`<label>${label}<select name="${name}">${items.map(([v,t])=>`<option value="${h(v)}" ${String(v)===String(selectedVal)?'selected':''}>${h(t)}</option>`).join('')}</select></label>`;
function openModal(type,id){let fields='',title='',url='',method='POST';if(type==='member'||type==='editmember'){const m=members().find(m=>m.id===id)||{};title=type==='member'?'Yeni üye ekle':'Üyeyi düzenle';url=type==='member'?'/api/members':'/api/members/'+id;method=type==='member'?'POST':'PATCH';fields=fld('Ad soyad','name','text',m.name||'','required')+fld('Telefon','phone','tel',m.phone||'')+fld('E-posta','email','email',m.email||'')+sel('Üyelik paketi','plan',[['Aylık + 8 Ders','Aylık + 8 Ders'],['Pilates 8 Ders','Pilates 8 Ders'],['Aylık Fitness','Aylık Fitness'],['3 Aylık','3 Aylık']],m.plan)+fld('Bitiş tarihi','expires','date',m.expires||localDay(30),'required')+fld('Ders hakkı','credits','number',m.credits??8,'min="0"')+(type==='editmember'?sel('Durum','status',[['Aktif','Aktif'],['Pasif','Pasif']],m.status):'')}
if(type==='lead'){title='Yeni müşteri adayı';url='/api/leads';fields=fld('Ad soyad','name','text','','required')+fld('Telefon','phone','tel','')+fld('İlgilendiği hizmet','interest','text','Pilates')+fld('Not','note','text','')}
if(type==='student'){if(role!=='teacher'){notify('Yalnızca eğitmen yeni öğrenci ekleyebilir');return}const available=S.classes.filter(c=>c.trainer_id===teacherId&&c.starts_at.slice(0,10)>=localDay(0));if(!available.length){notify('Önce yönetici panelinden ileri tarihli ders oluşturulmalı');return}title='Yeni öğrenci ekle';url='/api/teacher/students';fields=fld('Öğrenci adı soyadı','name','text','','required')+fld('Telefon','phone','tel','')+sel('Kaydedileceği ders','class_id',available.slice().sort(byStart).map(c=>[c.id,c.title+' · '+TT.dateTime(c.starts_at,{weekday:true})]))+fld('Üyelik bitişi','expires','date',localDay(30),'required')+fld('Ders hakkı','credits','number',8,'required min="1" max="1000"')}
if(type==='class'){title='Yeni ders oluştur';url='/api/classes';fields=fld('Ders adı','title','text','','required')+sel('Eğitmen','trainer_id',S.trainers.map(t=>[t.id,t.name]))+fld('Başlangıç','starts_at','datetime-local',localDay(1)+'T18:30','required')+fld('Süre (dk)','duration','number',50)+fld('Kapasite','capacity','number',12)+fld('Stüdyo','studio','text','Stüdyo 1')}
if(type==='payment'){title='Yeni ödeme kaydı';url='/api/payments';fields=sel('Üye','member_id',members().map(m=>[m.id,m.name]))+fld('Tutar (₺)','amount','number',850,'min="1" required')+fld('Vade tarihi','due_date','date',localDay(0),'required')}
if(type==='measurement'){title='Yeni ölçüm';url='/api/measurements';fields=sel('Üye','member_id',members().map(m=>[m.id,m.name]),memberId)+fld('Ölçüm tarihi','measured_at','date',localDay(0),'required')+fld('Kilo (kg)','weight','number','','step="0.1"')+fld('Yağ oranı (%)','body_fat','number','','step="0.1"')+fld('Kas (kg)','muscle','number','','step="0.1"')}
if(type==='announcement'){title='Yeni duyuru';url='/api/announcements';fields=fld('Başlık','title','text','','required')+'<label class="wide">Duyuru metni<textarea name="body" required></textarea></label>'}
modal(title,fields);document.getElementById('entryForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target).entries());for(const k of ['credits','class_id','trainer_id','duration','capacity','member_id','amount','weight','body_fat','muscle'])if(k in data)data[k]=Number(data[k]||0);try{await request(url,method,data);document.getElementById('modal')?.remove();await refresh();notify('Kayıt başarıyla kaydedildi')}catch(err){notify('Hata: '+err.message)}}}

async function showMemberProfile(id){selectedMemberProfile=id;try{notes=await request('/api/members/'+id+'/notes');page='memberDetail';draw()}catch(e){notify(e.message)}}
function specialForm(title,fields,callback){modal(title,fields);document.getElementById('entryForm').onsubmit=async e=>{e.preventDefault();try{await callback(Object.fromEntries(new FormData(e.target)));document.getElementById('modal')?.remove();await refresh();if(selectedMemberProfile&&page==='memberDetail')notes=await request('/api/members/'+selectedMemberProfile+'/notes');draw();notify('Kayıt tamamlandı')}catch(err){notify(err.message)}}}
function newUserModal(){
 const fields=fld('Kullanıcı adı','username','text','','required')+fld('Şifre (min. 10 karakter)','password','password','','required minlength="10"')+sel('Rol','role',[['member','Üye'],['teacher','Eğitmen'],['admin','Yönetici']],'member')+sel('Üye bağlantısı','member_id',members().map(m=>[m.id,m.name]))+sel('Eğitmen bağlantısı','trainer_id',S.trainers.map(t=>[t.id,t.name]));
 modal('Yeni kullanıcı hesabı',fields,'Hesabı oluştur');
 document.getElementById('entryForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await request('/api/users','POST',data);document.getElementById('modal')?.remove();notify('Hesap oluşturuldu')}catch(err){notify('Hata: '+err.message)}};
}
document.addEventListener('submit',async e=>{const f=e.target,id=f.id;if(!['v6SettingsForm','v6PostForm','v6FoodForm','v6LogForm'].includes(id)&&!f.classList.contains('v6CommentForm'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));try{if(id==='v6SettingsForm'){d.booking_window_days=Number(d.booking_window_days);d.community_post_roles=[...f.querySelectorAll('[name=posts]:checked')].map(x=>x.value);d.community_comment_roles=[...f.querySelectorAll('[name=comments]:checked')].map(x=>x.value);await request('/api/v6/settings','PATCH',d)}else if(id==='v6PostForm')await request('/api/v6/community','POST',d);else if(id==='v6FoodForm')await request('/api/v6/foods','POST',d);else if(id==='v6LogForm'){d.member_id=role==='member'?memberId:V6.memberFilter;d.product_id=Number(d.product_id);d.grams=Number(d.grams);await request('/api/v6/food-logs','POST',d)}else await request('/api/v6/community/'+f.dataset.id+'/comments','POST',d);await refresh();notify('Kaydedildi')}catch(err){notify('Hata: '+err.message)}});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-role],[data-page],[data-day],[data-act]');if(!target)return;if(target.dataset.role){return}if(target.dataset.page){page=target.dataset.page;history.replaceState(null,'','#'+page);search='';draw();focusTitle();return}if(target.dataset.day){day=Number(target.dataset.day);draw();return}const a=target.dataset.act;if(!a)return;if(a.startsWith('week:')){weekOffset=a==='week:prev'?weekOffset-1:a==='week:next'?weekOffset+1:0;draw();return}if(a.startsWith('v6calendar:')){v6CalendarMode=a.split(':')[1];draw();return}if(a.startsWith('v6month:')){v6MonthOffset=a.endsWith('prev')?v6MonthOffset-1:a.endsWith('next')?v6MonthOffset+1:0;v6CalendarDate=null;draw();return}if(a.startsWith('v6date:')){v6CalendarDate=a.slice(7);draw();return}if(a.startsWith('v6deletepost:')||a.startsWith('v6deletecomment:')||a.startsWith('v6deletelog:')){if(!confirm('Bu kayıt silinsin mi?'))return;const id=a.split(':')[1];const url=a.startsWith('v6deletepost:')?'/api/v6/community/'+id:a.startsWith('v6deletecomment:')?'/api/v6/comments/'+id:'/api/v6/food-logs/'+id;try{await request(url,'DELETE');await refresh()}catch(err){notify(err.message)}return}if(a.startsWith('v6repeat:')){const id=Number(a.split(':')[1]);const weeks=Number(prompt('Bu ders kaç hafta ileriye kopyalansın? (1-52)','12'));if(!Number.isInteger(weeks))return;try{const r=await request('/api/v6/classes/repeat','POST',{class_id:id,weeks});await refresh();notify(r.created+' ders oluşturuldu')}catch(err){notify(err.message)}return}if(a==='menu'){menuOpener=target;toggleMenu();return}if(a==='reloadmodule'){draw();return}if(a==='retry'){app.innerHTML='<div class="app-loading" role="status"><span class="spinner" aria-hidden="true"></span>FORM CLUB yükleniyor…</div>';await refresh();return}if(a==='hidehint'){try{localStorage.setItem('formclub:ios-hint','1')}catch{}target.parentElement.remove();return}if(a==='logout'){await logout(target);return}if(a==='menu-close'){toggleMenu(false);return}if(a==='skip'){e.preventDefault();document.getElementById('module-content')?.focus();return}if(a.startsWith('csv:')){downloadCsv(a.split(':')[1]);return}if(a.startsWith('profile:')){await showMemberProfile(Number(a.split(':')[1]));return}if(a.startsWith('note:')){const id=Number(a.split(':')[1]);specialForm('Üye notu ekle',fld('Not (maks. 1000 karakter)','note','text','','required maxlength="1000"'),async data=>request('/api/members/'+id+'/notes','POST',data));return}if(a.startsWith('renew:')){const id=Number(a.split(':')[1]),m=members().find(x=>x.id===id);specialForm('Üyelik yenile',fld('Yeni bitiş tarihi','expires','date',localDay(30),'required')+fld('Yeni toplam ders hakkı','credits','number',m.credits,'min="0" max="1000" required'),async data=>request('/api/members/'+id+'/renew','POST',{expires:data.expires,credits:Number(data.credits)}));return}if(a.startsWith('leadstage:')){const id=Number(a.split(':')[1]),lead=L.find(x=>x.id===id);specialForm('Müşteri adayı aşaması',sel('Aşama','stage',['Yeni','Arandı','Deneme Dersi','Üyeye Dönüştü','Kaybedildi'].map(x=>[x,x]),lead.stage),async data=>request('/api/leads/'+id,'PATCH',data));return}if(a==='newuser'){newUserModal();return}if(a==='close'){document.getElementById('modal')?.remove();return}if(a.startsWith('go:')){page=a.split(':')[1];draw();focusTitle();return}if(a.startsWith('modal:')){openModal(a.split(':')[1]);return}if(a.startsWith('editmember:')){openModal('editmember',Number(a.split(':')[1]));return}if(a.startsWith('reserve:')){await action('/api/bookings',{member_id:memberId,class_id:Number(a.split(':')[1])});return}if(a.startsWith('cancel:')){if(confirm('Rezervasyon iptal edilsin mi?'))await action('/api/bookings/'+a.split(':')[1]+'/cancel');return}if(a.startsWith('attend:')||a.startsWith('absent:')){await action('/api/bookings/'+a.split(':')[1]+'/attendance',{present:a.startsWith('attend:')});return}if(a.startsWith('pay:')){await action('/api/payments/'+a.split(':')[1]+'/pay');return}});
document.addEventListener('change',e=>{if(e.target.dataset.dashboard){FormClubDashboard.selection(adminDashboard,e.target.dataset.dashboard,e.target.type==='checkbox'?e.target.checked:e.target.value);draw();return}if(e.target.id==='v6MemberFilter'){V6.memberFilter=Number(e.target.value);request('/api/v6/food-logs?member_id='+V6.memberFilter).then(v=>{V6.logs=v;draw()}).catch(err=>notify(err.message));return}if(e.target.id==='memberSelect'){memberId=Number(e.target.value);draw()}if(e.target.id==='teacherSelect'){teacherId=Number(e.target.value);draw()}});
document.addEventListener('input',e=>{if(e.target.id==='searchInput'){search=e.target.value;let start=e.target.selectionStart;draw();const input=document.getElementById('searchInput');input.focus();input.setSelectionRange(start,start)}});

function attendanceView(){const list=S.classes.filter(c=>role==='admin'||c.trainer_id===teacherId);return `<section class="panel"><h2>Yoklama</h2>${list.slice().sort(byStart).map(c=>`<h3>${h(c.title)} · ${h(TT.dateTime(c.starts_at,{weekday:true}))}</h3>${S.bookings.filter(b=>b.class_id===c.id&&['reserved','attended','absent'].includes(b.status)).map(b=>`<div class="teacher-person"><span class="name">${h(b.member)}</span>${pill(b.status)}${btn('Geldi','attend:'+b.id,'small')}${btn('Gelmedi','absent:'+b.id,'small')}</div>`).join('')||'<p>Kayıt yok.</p>'}`).join('')||'<p>Ders yok.</p>'}</section>`}
function reservationView(){const upcoming=S.classes.filter(c=>!TT.isPast(c.starts_at)).sort(byStart),days=[...new Set(upcoming.map(c=>TT.dayKey(c.starts_at)))],shown=resDay&&days.includes(resDay)?upcoming.filter(c=>TT.dayKey(c.starts_at)===resDay):upcoming;
 const groups=[...new Set(shown.map(c=>TT.dayKey(c.starts_at)))].map(d=>`<optgroup label="${h(TT.date(d,{weekday:true}))}">${shown.filter(c=>TT.dayKey(c.starts_at)===d).map(c=>`<option value="${c.id}">${h(TT.time(c.starts_at))} · ${h(c.title)} (${h(c.studio||'')})</option>`).join('')}</optgroup>`).join('');
 const bookings=S.bookings.slice().sort((a,b)=>String(b.starts_at||'').localeCompare(String(a.starts_at||'')));
 return `<section class="panel"><h2>Rezervasyonlar</h2><form id="adminBooking" class="v6-form">${sel('Üye','member_id',members().map(m=>[m.id,m.name]),resMember)}<label>Gün<select id="resDay"><option value="">Tüm yaklaşan günler (${upcoming.length} ders)</option>${days.map(d=>`<option value="${d}" ${d===resDay?'selected':''}>${h(TT.date(d,{weekday:true}))}</option>`).join('')}</select></label><label>Ders<select name="class_id" required>${groups||'<option value="" disabled selected>Yaklaşan ders yok</option>'}</select></label><button class="btn primary" ${upcoming.length?'':'disabled'}>Rezervasyon oluştur</button></form><p class="muted small">Yalnızca başlamamış dersler listelenir. Geçmiş rezervasyonlar aşağıda ve raporlarda görünmeye devam eder.</p>${bookings.map(b=>`<div class="teacher-person"><span class="name">${h(b.member)} · ${h(b.class_title)}${b.starts_at?`<div class="muted">${h(TT.dateTime(b.starts_at,{weekday:true}))}</div>`:''}</span>${pill(b.status)}${['reserved','waitlist'].includes(b.status)?btn('İptal','cancel:'+b.id,'small'):''}</div>`).join('')}</section>`}
document.addEventListener('change',e=>{const id=e.target?.id;if(id==='memberStatus')memberStatus=e.target.value;else if(id==='renewFilter')renewFilter=e.target.value;else if(id==='resDay'){resDay=e.target.value;resMember=document.querySelector?.('#adminBooking [name=member_id]')?.value||resMember}else return;draw();document.getElementById(id)?.focus()});
document.addEventListener('submit',async e=>{if(e.target.id!=='adminBooking')return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));await action('/api/bookings',{member_id:Number(d.member_id),class_id:Number(d.class_id)})});
function focusTitle(){document.getElementById('page-title')?.focus({preventScroll:true});window.scrollTo?.(0,0)}
let menuOpener=null;
const isPhone=()=>!!globalThis.matchMedia?.('(max-width: 899px)').matches;
// Phone drawer: modal while open (inert background, focus trapped, Escape closes, focus returns).
function toggleMenu(force){const side=document.getElementById('app-drawer');if(!side)return;const open=typeof force==='boolean'?force:!side.classList.contains('open');const modal=open&&isPhone();side.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);document.querySelectorAll('[data-act="menu"]').forEach(b=>b.setAttribute('aria-expanded',String(open)));const scrim=document.querySelector('.fc-scrim');if(scrim)scrim.hidden=!open;for(const el of document.querySelectorAll('.fc-app > .main, .fc-app > .tabbar, .fc-app > .fc-mobilebar')){if(modal)el.setAttribute('inert','');else el.removeAttribute('inert')}if(modal){side.setAttribute('role','dialog');side.setAttribute('aria-modal','true');(side.querySelector('[aria-current]')||side.querySelector('.fc-navlink'))?.focus()}else{side.removeAttribute('role');side.removeAttribute('aria-modal');if(force===false||!open){const back=menuOpener&&document.body.contains(menuOpener)?menuOpener:document.querySelector('.fc-burger');if(isPhone())back?.focus();menuOpener=null}}}
async function logout(button){if(button)button.disabled=true;try{await request('/api/logout','POST',{})}catch(err){if(button)button.disabled=false;notify('Çıkış yapılamadı: '+err.message+' Oturumun hâlâ açık olabilir.');return}try{globalThis.sessionStorage?.clear()}catch{}clearPrivateState();history.replaceState(null,'',location.pathname);document.getElementById('module-content')?.replaceChildren();document.body.classList.remove('menu-open');await refresh();notify('Çıkış yapıldı')}
document.addEventListener('keydown',e=>{const side=document.getElementById('app-drawer'),open=side?.classList.contains('open');if(e.key==='Tab'&&open&&isPhone()){const f=[...side.querySelectorAll('button:not([disabled]),a[href]')];if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}return}if(e.key!=='Escape')return;if(document.getElementById('modal')){document.getElementById('modal').remove();return}if(open)toggleMenu(false)});
function connectionStatus(){const el=document.getElementById('connection-status');if(el)el.hidden=navigator.onLine;if(!navigator.onLine)notify('Çevrimdışısın. Bağlantı gerekli.');else refresh()}
window.addEventListener('offline',connectionStatus);window.addEventListener('online',connectionStatus);
let installPrompt;
function showInstallPrompt(){const b=document.getElementById('install-app');if(b&&installPrompt){b.hidden=false;b.onclick=async()=>{const prompt=installPrompt;installPrompt=null;b.hidden=true;await prompt.prompt()}}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;showInstallPrompt()});
if(!NATIVE&&'serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(()=>notify('Çevrimdışı uygulama kabuğu hazırlanamadı'));

window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(account&&navItems[role].some(x=>x[0]===next)&&next!==page){page=next;draw()}});

/* ---------- Calorie target (energy.js) ---------- */
const energy={profile:null,status:{},loaded:false,loading:false,store:null};
function resetEnergy(){energy.profile=null;energy.status={};energy.loaded=false;energy.loading=false;energy.store=null}
function energyStore(){if(!energy.store)energy.store=FormClubEnergy.createStore({request,userId:account?.id});return energy.store}
async function loadEnergy(redraw=true){if(energy.loading||energy.loaded||!globalThis.FormClubEnergy)return;energy.loading=true;const owner=account?.id;try{const r=await energyStore().load();if(account?.id!==owner)return;energy.profile=r.profile;energy.status={server:r.server,persisted:r.server&&!!r.updatedAt,updatedAt:r.updatedAt}}catch(err){if(account?.id!==owner)return;energy.profile=FormClubEnergy.normalizeProfile(null);energy.status={loadError:err.message}}energy.loaded=true;energy.loading=false;if(redraw&&account&&['energy','profile','nutrition'].includes(page))draw()}
function energyView(){if(!globalThis.FormClubEnergy)return '';if(!energy.loaded){loadEnergy();return '<section class="panel" role="status" aria-busy="true">Kalori profili yükleniyor…</section>'}return FormClubEnergy.view(energy.profile,energy.status)}
function energySummary(){if(!globalThis.FormClubEnergy)return '';if(!energy.loaded){loadEnergy();return ''}const t=FormClubEnergy.resolveTarget(energy.profile);return `<section class="panel en-summary"><div><span class="muted">Günlük kalori hedefin</span><strong>${t.kcal?Number(t.kcal).toLocaleString('tr-TR')+' kcal':'Belirlenmedi'}</strong>${t.kcal?`<small class="muted">${t.source==='manual'?'Manuel hedef':'Otomatik hesap'}${energy.status.server===false||energy.status.dirty||energy.status.error||energy.status.local?' · taslak, hesabına kaydedilmedi':''}</small>`:''}</div><button class="btn small" type="button" data-page="energy">${t.kcal?'Düzenle':'Hesapla'}</button></section>`}
window.addEventListener('message',async e=>{const frame=document.querySelector('iframe.module-frame');if(!account||e.origin!==location.origin||e.source!==frame?.contentWindow||e.data?.type!=='formclub:nutrition-goals-updated')return;energy.loaded=false;await loadEnergy(false);const summary=document.querySelector('.en-summary');if(summary)summary.outerHTML=energySummary()});
function paintEnergy(){const res=document.getElementById('energy-result'),st=document.getElementById('energy-status');if(res)res.innerHTML=FormClubEnergy.resultView(energy.profile,{showErrors:energy.status.showErrors});if(st)st.innerHTML=FormClubEnergy.statusView(energy.status)}
document.addEventListener('input',e=>{const form=e.target.closest?.('#energyForm');if(!form||!energy.profile)return;energy.profile=FormClubEnergy.readForm(form,energy.profile);energy.status={...energy.status,persisted:false,local:false,error:'',dirty:true};const manual=form.querySelector('[name="manual_kcal"]');if(manual)manual.disabled=energy.profile.target_mode!=='manual';paintEnergy()});
document.addEventListener('change',e=>{const form=e.target.closest?.('#energyForm');if(!form||!energy.profile||e.target.type!=='radio'&&e.target.type!=='checkbox')return;energy.profile=FormClubEnergy.readForm(form,energy.profile);energy.status={...energy.status,persisted:false,local:false,error:'',dirty:true};const manual=form.querySelector('[name="manual_kcal"]');if(manual){manual.disabled=energy.profile.target_mode!=='manual';if(!manual.disabled&&e.target.name==='target_mode')manual.focus()}paintEnergy()});
document.addEventListener('submit',async e=>{if(e.target.id!=='energyForm')return;e.preventDefault();const profile=FormClubEnergy.readForm(e.target,energy.profile);energy.profile=profile;const check=FormClubEnergy.assess(profile),target=FormClubEnergy.resolveTarget(profile);const manualOk=profile.target_mode==='manual'&&target.kcal!==null;if(!manualOk&&(!check.ok||target.kcal===null)){energy.status={...energy.status,showErrors:true,dirty:true};draw();document.querySelector('#energyForm [aria-invalid="true"]')?.focus();return}energy.status={...energy.status,saving:true,showErrors:true};paintEnergy();const owner=account?.id;try{const r=await energyStore().save(profile);if(account?.id!==owner)return;energy.profile=r.profile;energy.status={server:r.server,persisted:r.persisted,local:!r.persisted,updatedAt:r.updatedAt,showErrors:true};notify(r.persisted?'Hesabına kaydedildi':'Bu oturumda kullanılacak; hesabına kaydedilmedi')}catch(err){if(account?.id!==owner)return;energy.status={...energy.status,saving:false,error:err.message}}draw()});

